#import <Foundation/Foundation.h>
static NSDictionary *run(NSArray *args){NSTask*t=[NSTask new];t.launchPath=@"/usr/sbin/diskutil";t.arguments=args;NSPipe*p=[NSPipe pipe];t.standardOutput=p;t.standardError=[NSFileHandle fileHandleWithStandardError];[t launch];NSData*d=[[p fileHandleForReading]readDataToEndOfFile];[t waitUntilExit];if(t.terminationStatus)@throw [NSException exceptionWithName:@"DiskOperationFailed" reason:args.description userInfo:nil];return [NSPropertyListSerialization propertyListWithData:d options:0 format:nil error:nil];}
static NSDictionary *group(NSDictionary*groups,NSString*uuid,NSString*device){for(NSDictionary*c in groups[@"Containers"])for(NSDictionary*g in c[@"VolumeGroups"]){if(![g[@"APFSVolumeGroupUUID"]isEqual:uuid])continue;BOOL ok=NO;for(NSDictionary*v in g[@"Volumes"])if([v[@"Role"]isEqual:@"System"]){NSString*base=v[@"DeviceIdentifier"];ok=[device isEqual:base]||[device hasPrefix:[base stringByAppendingString:@"s"]];}if(ok)return @{@"container":c,@"group":g};}return nil;}
static NSDictionary *mountInfo(NSString*disk){NSDictionary*i=run(@[@"info",@"-plist",disk]);if(![i[@"MountPoint"]isKindOfClass:NSString.class]){run(@[@"mount",disk]);i=run(@[@"info",@"-plist",disk]);}if(![i[@"MountPoint"]isKindOfClass:NSString.class])@throw [NSException exceptionWithName:@"VolumeNotMounted" reason:@"Unlock the installed Tahoe volumes using Disk Utility, then retry." userInfo:nil];return i;}
int main(int argc,const char**argv){@autoreleasepool{@try{
 if(argc==2&&!strcmp(argv[1],"--self-test")){NSDictionary*groups=@{@"Containers":@[@{@"ContainerReference":@"disk3",@"VolumeGroups":@[@{@"APFSVolumeGroupUUID":@"G",@"Volumes":@[@{@"Role":@"System",@"DeviceIdentifier":@"disk3s1"},@{@"Role":@"Data",@"DeviceIdentifier":@"disk3s5"}]}]}]};if(!group(groups,@"G",@"disk3s1")||!group(groups,@"G",@"disk3s1s1")||group(groups,@"G",@"disk3s5")||group(groups,@"WRONG",@"disk3s1"))return 2;puts("PASS System/snapshot matching, Data-role rejection and cross-group rejection; no disk operations");return 0;}
 if(argc!=2)return 2;NSString*root=[[@(argv[1]) stringByStandardizingPath]stringByResolvingSymlinksInPath];if([root isEqual:@"/"]||![root hasPrefix:@"/Volumes/"])@throw [NSException exceptionWithName:@"InvalidTarget" reason:@"Select the installed Tahoe System volume under /Volumes, never the running Recovery root." userInfo:nil];
 NSDictionary*info=run(@[@"info",@"-plist",root]);NSString*uuid=info[@"APFSVolumeGroupID"];if(!uuid)uuid=info[@"APFSVolumeGroupUUID"];NSDictionary*match=group(run(@[@"apfs",@"listVolumeGroups",@"-plist"]),uuid,info[@"DeviceIdentifier"]);if(!match)@throw [NSException exceptionWithName:@"NoMatchingSystemGroup" reason:@"Target is not a System volume/snapshot in a valid APFS volume group." userInfo:nil];
 NSString*dataDisk=nil,*systemUUID=nil;for(NSDictionary*v in match[@"group"][@"Volumes"])if([v[@"Role"]isEqual:@"System"])systemUUID=v[@"DiskUUID"];if(!systemUUID)return 2;for(NSDictionary*v in match[@"group"][@"Volumes"])if([v[@"Role"]isEqual:@"Data"])dataDisk=v[@"DeviceIdentifier"];if(!dataDisk)return 2;NSDictionary*di=mountInfo(dataDisk);NSString*data=di[@"MountPoint"];if([data isEqual:root]||![di[@"WritableVolume"]boolValue])return 2;
 NSString*container=match[@"container"][@"ContainerReference"],*preDisk=nil;for(NSDictionary*c in run(@[@"apfs",@"list",@"-plist"])[@"Containers"]){if(![c[@"ContainerReference"]isEqual:container])continue;for(NSDictionary*v in c[@"Volumes"])if([v[@"Roles"]containsObject:@"Preboot"])preDisk=v[@"DeviceIdentifier"];}
 if(!preDisk)return 2;NSDictionary*pi=mountInfo(preDisk);NSString*pre=pi[@"MountPoint"];if([pre isEqual:@"/"]||![pi[@"WritableVolume"]boolValue])return 2;
 NSDictionary*version=[NSDictionary dictionaryWithContentsOfFile:[root stringByAppendingPathComponent:@"System/Library/CoreServices/SystemVersion.plist"]];if(![version[@"ProductVersion"]hasPrefix:@"26."])return 2;
 NSDictionary*out=@{@"SystemRoot":root,@"DataRoot":data,@"PrebootRoot":pre,@"VolumeGroup":uuid,@"SystemUUID":systemUUID,@"Build":version[@"ProductBuildVersion"],@"Version":version[@"ProductVersion"]};NSData*d=[NSPropertyListSerialization dataWithPropertyList:out format:NSPropertyListXMLFormat_v1_0 options:0 error:nil];[[NSFileHandle fileHandleWithStandardOutput]writeData:d];return 0;
 }@catch(NSException*e){fprintf(stderr,"%s: %s\n",e.name.UTF8String,e.reason.UTF8String);return 2;}}}
